  "Tələbə, məzun və işəgötürən üçün bir platforma": "One platform for students, graduates and employers",
  "Bakalavr və magistr tələbələri universitet e-poçtu ilə daxil olur və ixtisasına uyğun iş, təcrübə və könüllülük elanlarını uyğunluq faizi ilə görür.": "Bachelor's and master's students sign in with their university email and see jobs, internships and volunteering that fit their major, each with a match percentage.",
