  "Məzunlar": "Graduates",
  "Məzunlar şəxsi e-poçtla qeydiyyatdan keçir. Karyera Mərkəzi təsdiqindən sonra vakansiyalara müraciət edə və graduate proqramlarını izləyə bilərsən.": "Graduates sign up with a personal email. After the Career Center approves the account, you can apply for jobs and follow graduate programmes.",
  "Məzun kimi qoşul": "Join as a graduate",
  "İşəgötürənlər": "Employers",
  "Şirkətlər elanlarını uyğun fakültə və ixtisaslara yönəldir, müraciətləri uyğunluq faizinə görə sıralanmış görür.": "Companies target their listings at the right faculties and majors and see applications sorted by match percentage.",
  "Üç addımda uyğun imkana": "Three steps to the right opportunity",
  "Uyğunluq təsadüfi deyil: hər elan üçün fakültən, ixtisasın və bacarıqların ayrıca qiymətləndirilir və faizin haradan gəldiyini görürsən.": "The match is not random: for every listing your faculty, major and skills are scored separately, and you see where the percentage comes from.",
  "Universitet e-poçtunla bir neçə dəqiqəyə qeydiyyatdan keç.": "Sign up with your university email in a few minutes.",
  "Profilini doldur": "Fill in your profile",
  "Fakültəni, ixtisasını, kursunu və bacarıqlarını qeyd et. CV də bu məlumatlardan avtomatik qurulur.": "Add your faculty, major, year and skills. Your CV is built from this information automatically.",
  "Uyğun elana müraciət et": "Apply to the listings that fit",
  "Hər elanda sənin üçün hesablanmış faizi gör və ən uyğun imkanlara bir kliklə müraciət et.": "See the percentage calculated for you on every listing and apply to the best matches in one click.",
  "Karyerana hazırlaşmaq üçün hər şey bir yerdə": "Everything to prepare for your career in one place",
  "İşəgötürənlər üçün": "For employers",
  "ADNSU istedadlarını işə götürün": "Hire ASOIU talent",
  "Mühəndislik, IT, energetika, iqtisadiyyat və digər ixtisaslar üzrə tələbə və məzunlara birbaşa çıxış.": "Direct access to students and graduates in engineering, IT, energy, economics and other majors.",
  "Hədəfli elanlar": "Targeted listings",
  "Elanı fakültə və ixtisas üzrə hədəfləyin: onu ən uyğun tələbələr yüksək faizlə görür.": "Target a listing by faculty and major: the best-fitting students see it with a high percentage.",
  "Uyğunluq faizi ilə namizədlər": "Candidates with a match percentage",
  "Hər müraciətçinin vakansiyaya uyğunluğunu faizlə və çatışmayan bacarıqlarla görün.": "See each applicant's fit for the job as a percentage, with the missing skills.",
  "Müsahibə planlaması": "Interview scheduling",
  "Müsahibə dəvətləri göndərin və görüş vaxtlarını platformada idarə edin.": "Send interview invitations and manage meeting times on the platform.",
  "Karyera Mərkəzi ilə əməkdaşlıq": "Partnership with the Career Center",
  "Təcrübə proqramları, karyera yarmarkaları və infosessiyalar üçün birbaşa əlaqə.": "A direct line for internship programmes, career fairs and info sessions.",
  "Platformadakı şirkətlər": "Companies on the platform",
  "Bəli, tələbə və məzunlar üçün tamamilə pulsuzdur — platforma universitetin karyera xidmətinin bir hissəsidir.": "Yes, it is completely free for students and graduates — the platform is part of the university's career service.",
  "Şirkət elanı necə yerləşdirir?": "How does a company post a listing?",
  "Korporativ e-poçtla şirkət hesabı yaradın. Karyera Mərkəzi hesabı təsdiqlədikdən sonra vakansiya yarada bilərsiniz; hər elan yoxlanılır və təsdiqdən sonra uyğun tələbələrə göstərilir.": "Create a company account with a corporate email. Once the Career Center approves the account, you can create jobs; each listing is reviewed and, after approval, shown to matching students.",
  "Kabinetində sənə uyğun imkanlar var": "Opportunities that fit you are in your account",
  "Uyğunluq faizlərini, müraciətlərini və CV-ni kabinetində izlə.": "Follow your match percentages, applications and CV in your account.",
  "Karyerana bu gün başla": "Start your career today",
  "Qeydiyyat pulsuzdur və bir neçə dəqiqə çəkir.": "Sign-up is free and takes a few minutes.",
  "ADNSU tələbə və məzunlarını işəgötürənlərlə birləşdirən karyera platforması.": "A career platform connecting ASOIU students and graduates with employers."
