  "ADNSU tələbə bazasında bacarıq, fakültə, kurs və GPA üzrə axtarış.": "Поиск по базе студентов АГУНП: навыки, факультет, курс и GPA.",
  "ADNSU tələbə statusunla.": "По статусу студента АГУНП.",
  "ADNSU tələbə statusunuzla teatr, kino, muzey və digər məkanlarda endirim.": "Скидки в театрах, кино, музеях и других местах по статусу студента АГУНП.",
  "ADNSU tələbə və məzunlarını sənaye partnyorları ilə birləşdirən karyera platforması.": "Карьерная платформа, связывающая студентов и выпускников АГУНП с промышленными партнёрами.",
  "ADNSU tələbələri üçün ixtisasa görə avtomatik karyera matching platforması — iş, təcrübə, graduate proqramları, CV mərkəzi və müsahibə hazırlığı.": "Платформа автоматического карьерного подбора для студентов АГУНП по специальности — работа, стажировки, программы для выпускников, центр резюме и подготовка к собеседованиям.",
  "ADNSU tələbələri üçün iş, təcrübə, graduate proqramları və könüllülük imkanları — fakültənə, ixtisasına və bacarıqlarına görə avtomatik uyğunlaşdırılmış.": "Работа, стажировки, программы для выпускников и волонтёрство для студентов АГУНП — автоматически подобраны по факультету, специальности и навыкам.",
  "ADNSU tələbələri üçün iş, təcrübə, graduate proqramları və könüllülük. Sistem fakültən, ixtisasın və bacarıqlarına görə hər elana uyğunluq faizi hesablayır — özün axtarmırsan, uyğun olan sənə gəlir.": "Работа, стажировки, программы для выпускников и волонтёрство для студентов АГУНП. Система рассчитывает процент совпадения каждого объявления по вашему факультету, специальности и навыкам — вам не нужно искать, подходящее приходит само.",
  "ADNSU tələbələri, məzunları və tərəfdaş şirkətlərin paylaşımları.": "Публикации студентов, выпускников АГУНП и компаний-партнёров.",
  "ADNSU tələbələrini iş, təcrübə, graduate proqramları və könüllülük imkanları ilə birləşdirən universitet karyera platformasıdır. Fərqi odur ki, elanlar sadəcə siyahılanmır — hər tələbə üçün uyğunluq faizi hesablanır.": "Это университетская карьерная платформа, связывающая студентов АГУНП с работой, стажировками, программами для выпускников и волонтёрством. Её отличие: объявления не просто перечисляются — для каждого студента рассчитывается процент совпадения.",
  "ADNSU tələbələrinə elan verən tərəfdaşlar.": "Партнёры, публикующие объявления для студентов АГУНП.",
  "ADNSU · sənaye əməkdaşlığı": "АГУНП · сотрудничество с промышленностью",
