  "AI xidməti əlçatan olmadıqda sistem şəffaf lokal qiymətləndirmə ilə davam edir. Nəticə hazırlıq məqsədlidir.": "Когда сервис ИИ недоступен, система продолжает с прозрачной локальной оценкой. Результат — для подготовки.",
