  "Bakalavr və magistr təhsilini birlikdə göstər": "Показывать бакалавриат и магистратуру вместе",
  "Bakalavr və magistr tələbələri universitet e-poçtu (@asoiu.edu.az) ilə birbaşa daxil olur. Məzunlar şəxsi e-poçtla qeydiyyatdan keçə və Karyera Mərkəzinin yoxlamasından sonra tam giriş əldə edə bilər. Şirkətlər korporativ e-poçtla qeydiyyatdan keçir və təsdiqdən sonra elan dərc edir.": "Бакалавры и магистранты входят напрямую с университетским email (@asoiu.edu.az). Выпускники могут зарегистрироваться с личным email и получить полный доступ после проверки Карьерным центром. Компании регистрируются с корпоративным email и публикуют объявления после утверждения.",
  "Bakalavr, magistr və məzun hesabları": "Аккаунты бакалавров, магистрантов и выпускников",
  "Bakalavr, magistr və məzun məlumatlarınızı bir profildə saxlayın. Dəqiq profil daha düzgün vakansiya və şəbəkə tövsiyələri verir.": "Храните данные бакалавриата, магистратуры и выпуска в одном профиле. Точный профиль даёт более точные рекомендации вакансий и контактов.",
  "Bakalavr, magistr, PhD və digər təhsil qeydlərini ayrıca əlavə edin.": "Добавляйте записи о бакалавриате, магистратуре, PhD и другом образовании отдельно.",
