  "Şirkət hesabları": "Аккаунты компаний",
  "Şirkət hesabları Karyera Mərkəzinin təsdiqindən sonra elan dərc edə bilir. Təsdiqə qədər kabinetə daxil ola, namizədləri görə bilərsiniz.": "Аккаунты компаний публикуют объявления после утверждения Карьерным центром. До этого можно входить в кабинет и видеть кандидатов.",
