  "Şirkətlər üçün": "Для компаний",
  "Kimlər üçündür": "Для кого",
  "Tələbə, məzun və işəgötürən üçün bir platforma": "Одна платформа для студентов, выпускников и работодателей",
  "Bakalavr və magistr tələbələri universitet e-poçtu ilə daxil olur və ixtisasına uyğun iş, təcrübə və könüllülük elanlarını uyğunluq faizi ilə görür.": "Студенты бакалавриата и магистратуры входят с университетской почтой и видят вакансии, стажировки и волонтёрство по своей специальности с процентом совпадения.",
  "Tələbə kimi başla": "Начать как студент",
  "Məzunlar": "Выпускники",
  "Məzunlar şəxsi e-poçtla qeydiyyatdan keçir. Karyera Mərkəzi təsdiqindən sonra vakansiyalara müraciət edə və graduate proqramlarını izləyə bilərsən.": "Выпускники регистрируются с личной почтой. После одобрения Карьерным центром можно откликаться на вакансии и следить за программами для выпускников.",
  "Məzun kimi qoşul": "Присоединиться как выпускник",
  "İşəgötürənlər": "Работодатели",
  "Şirkətlər elanlarını uyğun fakültə və ixtisaslara yönəldir, müraciətləri uyğunluq faizinə görə sıralanmış görür.": "Компании адресуют объявления нужным факультетам и специальностям и видят отклики, отсортированные по проценту совпадения.",
  "Üç addımda uyğun imkana": "Три шага к подходящей возможности",
  "Uyğunluq təsadüfi deyil: hər elan üçün fakültən, ixtisasın və bacarıqların ayrıca qiymətləndirilir və faizin haradan gəldiyini görürsən.": "Совпадение не случайно: для каждого объявления отдельно оцениваются ваш факультет, специальность и навыки, и вы видите, из чего складывается процент.",
  "Universitet e-poçtunla bir neçə dəqiqəyə qeydiyyatdan keç.": "Зарегистрируйтесь с университетской почтой за несколько минут.",
  "Profilini doldur": "Заполните профиль",
  "Fakültəni, ixtisasını, kursunu və bacarıqlarını qeyd et. CV də bu məlumatlardan avtomatik qurulur.": "Укажите факультет, специальность, курс и навыки. Резюме автоматически строится из этих данных.",
  "Uyğun elana müraciət et": "Откликайтесь на подходящие объявления",
  "Hər elanda sənin üçün hesablanmış faizi gör və ən uyğun imkanlara bir kliklə müraciət et.": "Смотрите процент, рассчитанный для вас в каждом объявлении, и откликайтесь на лучшие варианты в один клик.",
  "Karyerana hazırlaşmaq üçün hər şey bir yerdə": "Всё для подготовки к карьере в одном месте",
  "İşəgötürənlər üçün": "Для работодателей",
  "ADNSU istedadlarını işə götürün": "Нанимайте таланты АГУНП",
  "Mühəndislik, IT, energetika, iqtisadiyyat və digər ixtisaslar üzrə tələbə və məzunlara birbaşa çıxış.": "Прямой доступ к студентам и выпускникам инженерных, IT, энергетических, экономических и других специальностей.",
  "Hədəfli elanlar": "Адресные объявления",
  "Elanı fakültə və ixtisas üzrə hədəfləyin: onu ən uyğun tələbələr yüksək faizlə görür.": "Адресуйте объявление по факультету и специальности: самые подходящие студенты увидят его с высоким процентом.",
  "Uyğunluq faizi ilə namizədlər": "Кандидаты с процентом совпадения",
  "Hər müraciətçinin vakansiyaya uyğunluğunu faizlə və çatışmayan bacarıqlarla görün.": "Видите соответствие каждого кандидата вакансии в процентах и недостающие навыки.",
  "Müsahibə planlaması": "Планирование собеседований",
  "Müsahibə dəvətləri göndərin və görüş vaxtlarını platformada idarə edin.": "Отправляйте приглашения на собеседование и управляйте временем встреч на платформе.",
  "Karyera Mərkəzi ilə əməkdaşlıq": "Сотрудничество с Карьерным центром",
  "Təcrübə proqramları, karyera yarmarkaları və infosessiyalar üçün birbaşa əlaqə.": "Прямая связь для программ стажировок, ярмарок вакансий и инфосессий.",
  "Platformadakı şirkətlər": "Компании на платформе",
  "Bəli, tələbə və məzunlar üçün tamamilə pulsuzdur — platforma universitetin karyera xidmətinin bir hissəsidir.": "Да, для студентов и выпускников это полностью бесплатно — платформа является частью карьерной службы университета.",
  "Şirkət elanı necə yerləşdirir?": "Как компании разместить объявление?",
  "Korporativ e-poçtla şirkət hesabı yaradın. Karyera Mərkəzi hesabı təsdiqlədikdən sonra vakansiya yarada bilərsiniz; hər elan yoxlanılır və təsdiqdən sonra uyğun tələbələrə göstərilir.": "Создайте аккаунт компании с корпоративной почтой. После одобрения аккаунта Карьерным центром вы сможете создавать вакансии; каждое объявление проверяется и после одобрения показывается подходящим студентам.",
  "Kabinetində sənə uyğun imkanlar var": "В вашем кабинете есть подходящие возможности",
  "Uyğunluq faizlərini, müraciətlərini və CV-ni kabinetində izlə.": "Следите за процентами совпадения, откликами и резюме в своём кабинете.",
  "Karyerana bu gün başla": "Начните карьеру сегодня",
  "Qeydiyyat pulsuzdur və bir neçə dəqiqə çəkir.": "Регистрация бесплатна и занимает несколько минут.",
  "ADNSU tələbə və məzunlarını işəgötürənlərlə birləşdirən karyera platforması.": "Карьерная платформа, соединяющая студентов и выпускников АГУНП с работодателями."
